package com.bank.longestpalindrome;

import java.util.logging.Logger;

// Finds the longest palindromic substring for National Bank of India.
public class PalindromeFinder {
    private static final Logger log = Logger.getLogger(PalindromeFinder.class.getName());

    // Expand around every center (odd + even). O(n^2), O(1).
    public String longestPalindrome(String s) {
        if (s == null || s.isEmpty()) {
            return "";
        }
        int start = 0, end = 0;                 // best span [start..end]
        for (int i = 0; i < s.length(); i++) {
            int oddLen = expand(s, i, i);       // odd center on char i
            int evenLen = expand(s, i, i + 1);  // even center between i and i+1
            int len = Math.max(oddLen, evenLen);
            if (len > end - start + 1) {
                start = i - (len - 1) / 2;      // left bound from center + length
                end = i + len / 2;              // right bound
            }
        }
        String result = s.substring(start, end + 1);
        log.info(() -> "Longest palindrome = '" + result + "'");
        return result;
    }

    // Expand while both sides match; return the palindrome length.
    private int expand(String s, int left, int right) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            left--;
            right++;
        }
        return right - left - 1;                // characters strictly inside
    }
}
