package com.bank.longestpalindrome;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: longest palindromic substring in reference strings.
public class PalindromeFinderDemo {
    private static final Logger log = Logger.getLogger(PalindromeFinderDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        PalindromeFinder finder = new PalindromeFinder();

        log.info(() -> "Result = " + finder.longestPalindrome("babad"));  // "bab" or "aba"
        log.info(() -> "Result = " + finder.longestPalindrome("cbbd"));   // "bb"
        log.info(() -> "Result = " + finder.longestPalindrome("a"));      // "a"
    }
}
